/* A-Share National Team ETF Tracker: reads data/*.csv (generated by analyze.py) and draws the page.
   All text goes through i18n (dictionary in strings.js) and amounts through kit.amt / kit.shares / kit.yi;
   the whole page redraws on a language switch. Each time-series chart has its own range picker (default 1Y);
   the headline figures and official holdings do not depend on it. */
(function () {
  const { num, fmtPct, signCls } = kit;
  const t = (k, v) => i18n.t(k, v);
  const tv = (prefix, v) => (i18n.has(prefix + v) ? t(prefix + v) : v);   // translate data values, showing them as is when there is no entry
  const isZh = () => i18n.lang === 'zh';
  const FAM = [
    ['hs300', '沪深300'], ['sz50', '上证50/180'], ['zz500', '中证500'], ['zz1000', '中证1000'],
    ['cyb', '创业板'], ['kc50', '科创50'], ['a500', '中证A500'], ['other', '其他宽基'],
  ];
  const famName = (zh) => tv('f.', zh);
  const CAL_CAP = 600; // calendar colour scale saturation point (yi)
  const TOP_N = 3;     // number of contributing ETFs listed in the calendar tooltip
  const UPDATE_CMD = 'python -m investdiy.ashare_track_national_team_etf';
  const $ = (id) => document.getElementById(id);
  const el = (tag, cls, text) => { const e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; };
  const inRange = ([s, e]) => (r) => r.d >= s && r.d <= e;

  let D = null;          // loaded data
  const R = {};          // range pickers, one per chart
  let etfNameEn = new Map();
  const etfName = (r) => (isZh() ? r.name : r.name_en || etfNameEn.get(r.code) || r.name);

  /** "汇金资管 378.58；汇金投资 356.55" (yi units) -> translate holders and convert units for the language */
  const holderText = (detail) => (detail || '').split('；').filter(Boolean).map((part) => {
    const [g, v] = part.trim().split(/\s+/);
    return `${tv('h.', g)} ${kit.yi(num(v), 1)}`;
  }).join(' / ') || '—';

  function palette() {
    const up = kit.color('--up'), down = kit.color('--down'), neutral = kit.color('--neutral-cell');
    return {
      up, down,
      flow(v) {
        if (!isFinite(v) || Math.abs(v) < 3) return neutral;
        const s = Math.min(1, Math.sqrt(Math.abs(v) / CAL_CAP));
        return d3.interpolateRgb(neutral, v > 0 ? up : down)(0.18 + 0.82 * s);
      },
    };
  }

  // ---------------- header ----------------
  function drawHeader(k) {
    const set = (id, text, cls) => { const e = $(id); e.textContent = text; e.className = `kpi-value ${cls}`; };
    const f1 = num(k.flow_1d), f5 = num(k.flow_5d), f20 = num(k.flow_20d), fy = num(k.flow_ytd);
    set('k-1d', kit.amt(f1), signCls(f1));
    set('k-5d', kit.amt(f5), signCls(f5));
    set('k-20d', kit.amt(f20), signCls(f20));
    set('k-ytd', kit.amt(fy), signCls(fy));
    set('k-state', isZh() ? k.state : tv('vs.', k.state), k.state.startsWith('进场') ? 'up' : k.state.startsWith('退出') ? 'down' : '');
    $('k-1d-sub').textContent = `${k.as_of} · ${tv('v.', k.signal_1d)}`;
    $('k-th').textContent = t('k.th', { v: kit.amt(num(k.threshold), { sign: false }) });
    $('asof').textContent = t('common.asof', { d: k.as_of });
    $('k-pool').textContent = t('k.pool', { n: k.pool_size });
    set('k-floor', t('k.floor.value', { v: kit.amt(num(k.floor_amt), { sign: false }) }), 'down');
    $('k-floor-sub').textContent = t('k.floor.sub', {
      y: k.nt_base_date.slice(0, 4), base: kit.amt(num(k.nt_base_amt), { sign: false }), pct: k.floor_pct,
    });

    // two summary lines: current state / conclusion from official holdings
    if (k.episode_start) {
      const ef = num(k.episode_flow), ec = num(k.episode_csi300_chg);
      $('take-now').replaceChildren(...i18n.rich('take.wave', {
        asof: k.as_of, state: tv('v.', k.state), start: k.episode_start, days: k.episode_days,
        flow: kit.amt(ef), chg: fmtPct(ec),
      }), ec < 0 && ef > 0 ? t('take.contra') : '');
    } else {
      $('take-now').replaceChildren(...i18n.rich('take.none', { asof: k.as_of, flow: kit.amt(f1) }));
    }
    const basis = el('a', null, t('link.basis')); basis.href = '#holdings';
    $('take-hold').replaceChildren(
      ...i18n.rich('take.floor', { date: k.nt_base_date, base: kit.amt(num(k.nt_base_amt), { sign: false }), pct: `${k.floor_pct}%` }),
      ...(k.cap_date ? i18n.rich('take.cap', { date: k.cap_date, pct: `${k.cap_floor_pct}%` }) : []),
      t('take.end'), ' ', basis,
    );
  }

  // ---------------- cumulative flow vs CSI 300 (from the first day of the range) ----------------
  function drawCumulative(pal) {
    const box = $('cum-box'), tt = kit.tip($('cumulative')), S = kit.series();
    kit.ready(box);
    const [s0, e0] = R.cum.get();
    let acc = 0;
    const rows = D.daily.filter(inRange([s0, e0])).map((r) => ({ ...r, cum: (acc += r.flow) }));
    if (rows.length < 2) { kit.fail(box, t('common.failed')); return; }
    const eps = D.episodes.filter((e) => e.e >= s0 && e.s <= e0);
    const W = Math.max(280, box.clientWidth), H = 320, m = { t: 10, r: 52, b: 26, l: 62 };
    const x = d3.scaleUtc(d3.extent(rows, (r) => r.d), [m.l, W - m.r]);
    const y = d3.scaleLinear(d3.extent([0, ...rows.map((r) => r.cum)]), [H - m.b, m.t]).nice();
    const y2 = d3.scaleLinear(d3.extent(rows, (r) => r.idx), [H - m.b, m.t]).nice();
    const svg = d3.select(box).append('svg').attr('width', '100%').attr('viewBox', `0 0 ${W} ${H}`);
    svg.append('g').selectAll('rect').data(eps).join('rect')
      .attr('x', (e) => Math.max(m.l, x(e.s))).attr('width', (e) => Math.max(3, Math.min(W - m.r, x(e.e)) - Math.max(m.l, x(e.s)) + 3))
      .attr('y', m.t).attr('height', H - m.b - m.t)
      .style('fill', (e) => (e.side === '进场' ? pal.up : pal.down)).style('opacity', 0.16);
    const ax = svg.append('g').attr('transform', `translate(0,${H - m.b})`)
      .call(d3.axisBottom(x).ticks(Math.max(3, Math.floor(W / 110))).tickFormat(d3.utcFormat('%Y-%m')).tickSizeOuter(0));
    const ay = svg.append('g').attr('transform', `translate(${m.l},0)`)
      .call(d3.axisLeft(y).ticks(6).tickFormat(kit.axisYi).tickSize(-(W - m.l - m.r)));
    ay.select('.domain').remove();
    const ay2 = svg.append('g').attr('transform', `translate(${W - m.r},0)`)
      .call(d3.axisRight(y2).ticks(6).tickFormat(d3.format(',')).tickSize(0).tickPadding(6));
    ay2.select('.domain').remove();
    kit.axisStyle(ax, ay, ay2);
    svg.append('line').attr('x1', m.l).attr('x2', W - m.r).attr('y1', y(0)).attr('y2', y(0))
      .style('stroke', 'var(--axis)').style('stroke-dasharray', '4 3');
    svg.append('path').datum(rows).attr('d', d3.line((r) => x(r.d), (r) => y2(r.idx)))
      .style('fill', 'none').style('stroke', 'var(--muted-series)').style('stroke-width', 1.5).style('stroke-linejoin', 'round');
    svg.append('path').datum(rows).attr('d', d3.line((r) => x(r.d), (r) => y(r.cum)))
      .style('fill', 'none').style('stroke', S[0]).style('stroke-width', 2).style('stroke-linejoin', 'round');
    const rule = svg.append('line').attr('y1', m.t).attr('y2', H - m.b).style('stroke', 'var(--axis)').style('opacity', 0);
    const dot1 = svg.append('circle').attr('r', 3.5).style('fill', S[0]).style('opacity', 0);
    const dot2 = svg.append('circle').attr('r', 3).style('fill', 'var(--muted-series)').style('opacity', 0);
    const bis = d3.bisector((r) => r.d).center;
    svg.append('rect').attr('x', m.l).attr('y', m.t).attr('width', W - m.l - m.r).attr('height', H - m.t - m.b)
      .style('fill', 'transparent')
      .on('mousemove', (event) => {
        const r = rows[bis(rows, x.invert(d3.pointer(event)[0]))];
        rule.attr('x1', x(r.d)).attr('x2', x(r.d)).style('opacity', 1);
        dot1.attr('cx', x(r.d)).attr('cy', y(r.cum)).style('opacity', 1);
        dot2.attr('cx', x(r.d)).attr('cy', y2(r.idx)).style('opacity', 1);
        tt.show(event, [
          { text: r.date + (r.signal ? ` · ${tv('v.', r.signal)}` : '') },
          { text: t('cum.tipCum', { v: kit.amt(r.cum) }), color: S[0] },
          { text: t('cum.tipDay', { v: kit.amt(r.flow) }) },
          { text: t('cum.tipIdx', { v: kit.fmtNum(r.idx, 2), r: fmtPct(r.ret) }), color: 'var(--muted-series)' },
        ]);
      })
      .on('mouseleave', () => { tt.hide(); [rule, dot1, dot2].forEach((n) => n.style('opacity', 0)); });

    const item = (color, text, line) => {
      const s = el('span'); const i = el('i', line ? 'line' : null);
      i.style.background = color; if (!line) i.style.opacity = '0.35';
      s.append(i, text); return s;
    };
    $('cum-legend').replaceChildren(item(S[0], t('cum.lgCum'), true), item('var(--muted-series)', t('cum.lgIdx'), true),
      item(pal.up, t('cum.lgIn')), item(pal.down, t('cum.lgOut')));
  }

  // ---------------- calendar heatmap ----------------
  function topContributors(date) {
    const rs = (D.etfByDate.get(date) || []).filter((r) => Math.abs(r.flow) >= 1);
    return rs.sort((a, b) => Math.abs(b.flow) - Math.abs(a.flow)).slice(0, TOP_N);
  }

  function drawCalendar(pal) {
    const box = $('cal-box'), tt = kit.tip($('calendar'));
    kit.ready(box);
    const rowsAll = D.daily.filter(inRange(R.cal.get()));
    const W = Math.max(280, box.clientWidth), labelW = 36;
    const cell = Math.max(4, Math.min(16, Math.floor((W - labelW) / 54)));
    const years = d3.groups(rowsAll, (r) => r.d.getUTCFullYear()).sort((a, b) => b[0] - a[0]);
    const yearH = cell * 5 + 26;
    const svg = d3.select(box).append('svg').attr('width', '100%').attr('viewBox', `0 0 ${W} ${Math.max(1, years.length) * yearH}`);
    years.forEach(([yr, rs], i) => {
      const g = svg.append('g').attr('transform', `translate(0,${i * yearH + 16})`);
      const y0 = d3.utcYear(rs[0].d);
      const first = d3.utcMonth.floor(rs[0].d), last = rs[rs.length - 1].d;
      g.append('text').attr('x', 0).attr('y', cell * 2.5 + 4).text(yr).style('fill', 'var(--fg)').style('font-weight', 600);
      const months = d3.utcMonths(first, d3.utcDay.offset(last, 1)); // label only months covered by data
      g.selectAll('text.m').data(months).join('text').attr('class', 'm')
        .attr('x', (mo) => labelW + d3.utcMonday.count(y0, mo) * cell).attr('y', -5)
        .text((mo) => kit.monthLabel(mo));
      g.selectAll('rect').data(rs).join('rect')
        .attr('x', (r) => labelW + d3.utcMonday.count(y0, r.d) * cell)
        .attr('y', (r) => (r.d.getUTCDay() - 1) * cell)
        .attr('width', cell - 1.5).attr('height', cell - 1.5).attr('rx', Math.min(3, cell / 4))
        .style('fill', (r) => pal.flow(r.flow))
        .style('stroke', (r) => (r.signal.startsWith('强') ? 'var(--fg)' : 'none')).style('stroke-width', 1.5)
        .on('mousemove', (event, r) => {
          const top = topContributors(r.date);
          tt.show(event, [
            { text: r.date },
            { text: t('tip.flow', { v: kit.amt(r.flow) }) },
            { text: t('tip.csi', { v: fmtPct(r.ret) }) },
            { text: r.signal ? t('tip.signal', { s: tv('v.', r.signal) }) : tv('v.', '无信号') },
            ...(top.length ? [{ text: t('tip.top') }] : []),
            ...top.map((c) => ({ text: `${etfName(c)} ${kit.amt(c.flow)}`, color: c.flow > 0 ? pal.up : pal.down })),
          ]);
        })
        .on('mouseleave', () => tt.hide());
    });

    const lg = $('cal-legend');
    lg.replaceChildren(...[-600, -300, -100, -20, 20, 100, 300, 600].map((v) => {
      const s = el('span'); const i = el('i'); i.style.background = pal.flow(v);
      s.append(i, (v > 0 ? '+' : '−') + (isZh() ? Math.abs(v) : Math.abs(v) / 10)); return s;
    }));
    const s = el('span'); const i = el('i'); i.style.outline = '1.5px solid var(--fg)'; i.style.outlineOffset = '-1.5px';
    s.append(i, t('cal.strong')); lg.appendChild(s);
  }

  // ---------------- monthly by index family ----------------
  function drawMonthly() {
    const box = $('mon-box'), tt = kit.tip($('monthly')), S = kit.series();
    kit.ready(box);
    const [s0, e0] = R.mon.get();
    const m0 = d3.utcFormat('%Y-%m')(s0), m1 = d3.utcFormat('%Y-%m')(e0);
    const rows = D.monthly.filter((r) => r.month >= m0 && r.month <= m1);
    if (!rows.length) { kit.fail(box); return; }
    const used = FAM.map(([k], i) => ({ k, i })).filter((o) => rows.some((r) => r[o.k] !== 0)); // hide index families without data
    const W = Math.max(280, box.clientWidth), H = 300, m = { t: 10, r: 8, b: 26, l: 62 };
    const series = d3.stack().keys(used.map((o) => o.k)).offset(d3.stackOffsetDiverging)(rows);
    const x = d3.scaleBand(rows.map((r) => r.month), [m.l, W - m.r]).padding(0.2);
    const lo = d3.min(series, (s) => d3.min(s, (d) => d[0])) ?? 0, hi = d3.max(series, (s) => d3.max(s, (d) => d[1])) ?? 0;
    const y = d3.scaleLinear([Math.min(0, lo), Math.max(0, hi, 1)], [H - m.b, m.t]).nice();
    const svg = d3.select(box).append('svg').attr('width', '100%').attr('viewBox', `0 0 ${W} ${H}`);
    const ay = svg.append('g').attr('transform', `translate(${m.l},0)`)
      .call(d3.axisLeft(y).ticks(6).tickFormat(kit.axisYi).tickSize(-(W - m.l - m.r)));
    ay.select('.domain').remove();
    const every = Math.ceil(rows.length / Math.max(3, Math.floor(W / 64)));
    const ax = svg.append('g').attr('transform', `translate(0,${H - m.b})`)
      .call(d3.axisBottom(x).tickValues(rows.map((r) => r.month).filter((_, i) => i % every === 0))
        .tickFormat((s) => s.slice(2)).tickSize(0).tickPadding(8));
    ax.select('.domain').remove();
    kit.axisStyle(ax, ay);
    svg.append('g').selectAll('g').data(series).join('g').style('fill', (_, j) => S[used[j].i])
      .selectAll('rect').data((s) => s).join('rect')
      .attr('x', (d) => x(d.data.month)).attr('width', x.bandwidth())
      .attr('y', (d) => y(Math.max(d[0], d[1]))).attr('height', (d) => Math.abs(y(d[0]) - y(d[1])));
    svg.append('line').attr('x1', m.l).attr('x2', W - m.r).attr('y1', y(0)).attr('y2', y(0)).style('stroke', 'var(--axis)');
    svg.append('g').selectAll('rect').data(rows).join('rect')
      .attr('x', (r) => x(r.month) - (x.step() * x.paddingInner()) / 2).attr('width', x.step())
      .attr('y', m.t).attr('height', H - m.t - m.b).style('fill', 'transparent')
      .on('mousemove', (event, r) => tt.show(event, [
        { text: t('mon.tip', { m: r.month, v: kit.amt(r.total) }) },
        ...used.map((o) => ({ text: `${famName(FAM[o.i][1])} ${kit.amt(r[o.k])}`, color: S[o.i] })),
      ]))
      .on('mouseleave', () => tt.hide());
    $('mon-legend').replaceChildren(...used.map((o) => {
      const s = el('span'); const sw = el('i'); sw.style.background = S[o.i]; s.append(sw, famName(FAM[o.i][1])); return s;
    }));
  }

  // ---------------- per-ETF small multiples (sorted by size, hoverable) ----------------
  function drawSmall(pal) {
    const box = $('sm-box'), S = kit.series();
    const fl = new Map(D.floor.map((f) => [f.code, f]));
    kit.ready(box);
    const [s0, e0] = R.sm.get();
    const ordered = D.summary.slice().sort((a, b) => num(b.aum_yi) - num(a.aum_yi));
    ordered.forEach((s, idx) => {
      const rs = (D.etfByCode.get(s.code) || []).filter(inRange([s0, e0]));
      const cell = el('div', 'sm');
      const top = el('div', 'sm-row');
      top.append(el('span', 'sm-name', etfName(s)), el('span', 'sm-muted', kit.shares(num(s.shares_yi))));
      const chart = el('div');
      const foot = el('div', 'sm-row');
      const f20 = num(s.flow_20d);
      foot.append(el('span', 'sm-muted', t('sm.foot', { code: s.code })), el('span', signCls(f20), kit.amt(f20)));
      cell.append(top, chart, foot);
      box.appendChild(cell);
      if (rs.length < 2) return;
      const W = Math.max(120, chart.clientWidth || 160), H = 56;
      const x = d3.scaleUtc([s0, e0], [1, W - 1]);
      const f = fl.get(s.code);
      const baseDate = f ? new Date(f.base_date) : null;
      const base = f && baseDate <= e0 ? num(f.base_nt_yi) : NaN;
      const y = d3.scaleLinear(d3.extent([...rs.map((r) => r.sh), ...(isFinite(base) ? [base] : [])]), [H - 2, 2]);
      const svg = d3.select(chart).append('svg').attr('width', '100%').attr('viewBox', `0 0 ${W} ${H}`);
      const gid = `g-sm-${idx}`;
      const grad = svg.append('defs').append('linearGradient').attr('id', gid).attr('x1', 0).attr('x2', 0).attr('y1', 0).attr('y2', 1);
      [[0, 0.26], [0.25, 0.16], [0.5, 0.08], [0.75, 0.03], [1, 0]].forEach(([o, a]) =>
        grad.append('stop').attr('offset', o).style('stop-color', S[0]).style('stop-opacity', a));
      svg.append('path').datum(rs).attr('d', d3.area((r) => x(r.d), H, (r) => y(r.sh))).style('fill', `url(#${gid})`);
      svg.append('path').datum(rs).attr('d', d3.line((r) => x(r.d), (r) => y(r.sh)))
        .style('fill', 'none').style('stroke', S[0]).style('stroke-width', 1.5).style('stroke-linejoin', 'round');
      if (isFinite(base)) {
        const x0 = Math.max(1, x(baseDate < s0 ? s0 : baseDate));
        svg.append('line').attr('x1', x0).attr('x2', W - 1).attr('y1', y(base)).attr('y2', y(base))
          .style('stroke', 'var(--down)').style('stroke-width', 1.2).style('stroke-dasharray', '3 2');
      }
      const last = rs[rs.length - 1];
      svg.append('circle').attr('cx', x(last.d)).attr('cy', y(last.sh)).attr('r', 2.5).style('fill', S[0]);
      // hover
      const tt = kit.tip(cell);
      const dot = svg.append('circle').attr('r', 3).style('fill', S[0]).style('opacity', 0);
      const bis = d3.bisector((r) => r.d).center;
      svg.append('rect').attr('width', W).attr('height', H).style('fill', 'transparent')
        .on('mousemove', (event) => {
          const r = rs[bis(rs, x.invert(d3.pointer(event)[0]))];
          dot.attr('cx', x(r.d)).attr('cy', y(r.sh)).style('opacity', 1);
          tt.show(event, [{ text: r.date }, { text: t('sm.tip', { s: kit.shares(r.sh) }) },
            { text: t('sm.tipFlow', { f: kit.amt(r.flow) }), color: r.flow > 0 ? pal.up : r.flow < 0 ? pal.down : null }]);
        })
        .on('mouseleave', () => { tt.hide(); dot.style('opacity', 0); });
    });
  }

  // ---------------- official holdings (per disclosure period) ----------------
  function drawHoldings() {
    const rows = D.ntHist;
    const box = $('hold-box'), tt = kit.tip($('holdings')), S = kit.series();
    kit.ready(box);
    const used = FAM.map(([k], i) => ({ k, i })).filter((o) => rows.some((r) => r[o.k] > 0));
    const W = Math.max(260, box.clientWidth), H = 280, m = { t: 14, r: 8, b: 26, l: 56 };
    const series = d3.stack().keys(used.map((o) => o.k))(rows);
    const x = d3.scaleBand(rows.map((r) => r.period_end), [m.l, W - m.r]).padding(0.3);
    const y = d3.scaleLinear([0, d3.max(rows, (r) => r.total) || 1], [H - m.b, m.t]).nice();
    const svg = d3.select(box).append('svg').attr('width', '100%').attr('viewBox', `0 0 ${W} ${H}`);
    const ay = svg.append('g').attr('transform', `translate(${m.l},0)`)
      .call(d3.axisLeft(y).ticks(5).tickFormat(kit.axisYi).tickSize(-(W - m.l - m.r)));
    ay.select('.domain').remove();
    const ax = svg.append('g').attr('transform', `translate(0,${H - m.b})`)
      .call(d3.axisBottom(x).tickValues(rows.map((r) => r.period_end)
        .filter((_, i, a) => (a.length - 1 - i) % Math.ceil(a.length / Math.max(3, Math.floor(W / 64))) === 0)) // pick labels backwards from the last bar so the latest period is labelled without crowding
        .tickFormat((d) => d.slice(0, 7)).tickSize(0).tickPadding(8));
    ax.select('.domain').remove();
    kit.axisStyle(ax, ay);
    svg.append('g').selectAll('g').data(series).join('g').style('fill', (_, j) => S[used[j].i])
      .selectAll('rect').data((sr) => sr).join('rect')
      .attr('x', (d) => x(d.data.period_end)).attr('width', x.bandwidth())
      .attr('y', (d) => y(d[1])).attr('height', (d) => Math.max(0, y(d[0]) - y(d[1])))
      .style('opacity', (d) => (d.data.kind === '上限' ? 0.35 : 1));
    svg.append('g').selectAll('text').data(x.step() >= 44 ? rows : rows.slice(-2)).join('text')
      .attr('x', (r) => x(r.period_end) + x.bandwidth() / 2).attr('y', (r) => y(r.total) - 4).attr('text-anchor', 'middle')
      .text((r) => (r.kind === '上限' ? '≤' : '') + kit.yi(r.total));
    svg.append('g').selectAll('rect').data(rows).join('rect')
      .attr('x', (r) => x(r.period_end)).attr('width', x.bandwidth()).attr('y', m.t).attr('height', H - m.t - m.b)
      .style('fill', 'transparent')
      .on('mousemove', (event, r) => tt.show(event, [
        { text: t(r.kind === '上限' ? 'hold.tipCap' : 'hold.tipDisclosed', { d: r.period_end, v: kit.amt(r.total, { sign: false }) }) },
        ...used.filter((o) => r[o.k] > 0).map((o) => ({ text: `${famName(FAM[o.i][1])} ${kit.amt(r[o.k], { sign: false })}`, color: S[o.i] })),
      ]))
      .on('mouseleave', () => tt.hide());
    $('hold-legend').replaceChildren(...used.map((o) => {
      const sp = el('span'); const sw = el('i'); sw.style.background = S[o.i]; sp.append(sw, famName(FAM[o.i][1])); return sp;
    }));
  }

  // ---------------- confirmed selling lower bound (daily) ----------------
  function drawFloorDaily(pal) {
    const rows = D.floorDaily;
    const box = $('floor-box'), tt = kit.tip($('holdings'));
    kit.ready(box);
    if (!rows.length) { kit.fail(box, t('floor.empty')); return; }
    const W = Math.max(260, box.clientWidth), H = 280, m = { t: 14, r: 12, b: 26, l: 56 };
    const x = d3.scaleUtc(d3.extent(rows, (r) => r.d), [m.l, W - m.r]);
    const y = d3.scaleLinear([0, d3.max(rows, (r) => r.v) || 1], [H - m.b, m.t]).nice();
    const svg = d3.select(box).append('svg').attr('width', '100%').attr('viewBox', `0 0 ${W} ${H}`);
    const ay = svg.append('g').attr('transform', `translate(${m.l},0)`)
      .call(d3.axisLeft(y).ticks(5).tickFormat(kit.axisYi).tickSize(-(W - m.l - m.r)));
    ay.select('.domain').remove();
    const ax = svg.append('g').attr('transform', `translate(0,${H - m.b})`)
      .call(d3.axisBottom(x).ticks(Math.max(3, Math.floor(W / 90))).tickFormat(d3.utcFormat('%Y-%m')).tickSizeOuter(0));
    kit.axisStyle(ax, ay);
    const gid = 'g-floor';
    const grad = svg.append('defs').append('linearGradient').attr('id', gid).attr('x1', 0).attr('x2', 0).attr('y1', 0).attr('y2', 1);
    [[0, 0.3], [1, 0.02]].forEach(([o, a]) => grad.append('stop').attr('offset', o).style('stop-color', pal.down).style('stop-opacity', a));
    svg.append('path').datum(rows).attr('d', d3.area((r) => x(r.d), H - m.b, (r) => y(r.v))).style('fill', `url(#${gid})`);
    svg.append('path').datum(rows).attr('d', d3.line((r) => x(r.d), (r) => y(r.v)))
      .style('fill', 'none').style('stroke', pal.down).style('stroke-width', 2).style('stroke-linejoin', 'round');
    const dot = svg.append('circle').attr('r', 3.5).style('fill', pal.down).style('opacity', 0);
    const bis = d3.bisector((r) => r.d).center;
    svg.append('rect').attr('x', m.l).attr('y', m.t).attr('width', W - m.l - m.r).attr('height', H - m.t - m.b).style('fill', 'transparent')
      .on('mousemove', (event) => {
        const r = rows[bis(rows, x.invert(d3.pointer(event)[0]))];
        dot.attr('cx', x(r.d)).attr('cy', y(r.v)).style('opacity', 1);
        tt.show(event, [{ text: r.date }, { text: t('floor.tip', { v: kit.amt(r.v, { sign: false }) }), color: pal.down }]);
      })
      .on('mouseleave', () => { tt.hide(); dot.style('opacity', 0); });
    const sp = el('span'); const i = el('i', 'line'); i.style.background = pal.down; sp.append(i, t('floor.legend'));
    $('floor-legend').replaceChildren(sp);
  }

  // ---------------- pool table (flow / official holdings column groups) ----------------
  let poolMode = 'flow';
  const poolSort = { flow: { k: 'aum_yi', dir: -1 }, hold: { k: 'base_nt_yi', dir: -1 } };
  const sold = (v, p) => (num(v) > 0 ? t('ft.sold', { v: kit.yi(num(v), 1), p }) : null);
  const COLS = {
    flow: [
      { k: 'code', h: 'et.code' },
      { k: 'name', h: 'et.name', text: etfName, sortText: true },
      { k: 'family', h: 'et.family', text: (r) => famName(r.family), sortText: true },
      { k: 'shares_yi', h: 'et.shares', text: (r) => kit.yi(num(r.shares_yi), 1) },
      { k: 'aum_yi', h: 'et.aum', text: (r) => kit.yi(num(r.aum_yi)) },
      ...['flow_5d', 'flow_20d', 'flow_ytd'].map((k, i) => ({
        k, h: ['et.5d', 'et.20d', 'et.ytd'][i], text: (r) => kit.yi(num(r[k]), 0, true), cls: (r) => signCls(num(r[k])),
      })),
    ],
    hold: [
      { k: 'code', h: 'et.code' },
      { k: 'name', h: 'et.name', text: etfName, sortText: true },
      { k: 'holders', h: 'ft.holders', text: (r) => holderText(r.holders), sortText: true },
      { k: 'base_nt_yi', h: 'ft.base', text: (r) => (r.base_nt_yi ? kit.yi(num(r.base_nt_yi), 1) : '—') },
      { k: 'base_nt_pct', h: 'ft.pct', text: (r) => (r.base_nt_pct ? `${num(r.base_nt_pct).toFixed(1)}%` : '—') },
      { k: 'shares_yi', h: 'ft.shares', text: (r) => kit.yi(num(r.shares_yi), 1) },
      { k: 'floor_yi', h: 'ft.floor', text: (r) => (r.floor_yi === undefined ? '—' : sold(r.floor_yi, r.floor_pct) ?? t('ft.notBreached')),
        cls: (r) => (num(r.floor_yi) > 0 ? 'down' : '') },
      { k: 'breach_date', h: 'ft.breach', text: (r) => r.breach_date || '—', sortText: true },
      { k: 'cap_inst_yi', h: 'ft.inst', text: (r) => (r.cap_inst_yi ? kit.yi(num(r.cap_inst_yi), 1) : '—') },
      { k: 'cap_floor_yi', h: 'ft.cap', text: (r) => (!r.cap_floor_yi && r.cap_floor_yi !== '0.0' ? '—' : sold(r.cap_floor_yi, r.cap_floor_pct) ?? t('ft.unprovable')),
        cls: (r) => (num(r.cap_floor_yi) > 0 ? 'down' : '') },
    ],
  };

  function drawPoolTable() {
    const cols = COLS[poolMode], st = poolSort[poolMode];
    document.querySelectorAll('#pool-mode button').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.mode === poolMode)));
    $('pool-note').textContent = t(poolMode === 'flow' ? 'pool.noteFlow' : 'pool.noteHold');
    const tr = el('tr');
    cols.forEach((c) => {
      const th = el('th');
      th.setAttribute('aria-sort', c.k === st.k ? (st.dir > 0 ? 'ascending' : 'descending') : 'none');
      const b = el('button', null, t(c.h)); b.type = 'button';
      b.addEventListener('click', () => {
        st.dir = st.k === c.k ? -st.dir : (c.sortText || c.k === 'code' ? 1 : -1);
        st.k = c.k;
        drawPoolTable();
      });
      th.appendChild(b); tr.appendChild(th);
    });
    document.querySelector('#pool-table thead').replaceChildren(tr);
    const col = cols.find((c) => c.k === st.k);
    const val = (r) => {
      if (col.sortText) return col.text ? col.text(r) : r[col.k] || '';
      if (col.k === 'code') return r.code;
      const v = num(r[col.k]);
      return isFinite(v) ? v : -Infinity;
    };
    const rows = D.poolRows.slice().sort((a, b) => (val(a) > val(b) ? 1 : val(a) < val(b) ? -1 : 0) * st.dir);
    document.querySelector('#pool-table tbody').replaceChildren(...rows.map((r) => {
      const row = el('tr');
      cols.forEach((c) => row.appendChild(el('td', c.cls ? c.cls(r) : null, c.text ? c.text(r) : r[c.k])));
      return row;
    }));
  }

  function drawEpTable() {
    document.querySelector('#ep-table tbody').replaceChildren(...D.episodeRows.slice().sort((a, b) => (a.start < b.start ? 1 : -1)).map((r) => {
      const tr = el('tr');
      const td = (text, c) => { const d = el('td', c); d.append(text); tr.appendChild(d); };
      td(r.start); td(r.end);
      td(el('span', `pill ${r.side === '进场' ? 'up' : 'down'}`, tv('v.', r.side)));
      td(r.signal_days);
      td(kit.yi(num(r.flow_yi), 0, true), signCls(num(r.flow_yi)));
      td(kit.yi(num(r.peak_day_yi), 0, true), signCls(num(r.peak_day_yi)));
      td(r.hs300_pct === '' || r.hs300_pct === undefined ? '—' : `${num(r.hs300_pct).toFixed(0)}%`);
      td(fmtPct(num(r.csi300_chg)), signCls(num(r.csi300_chg)));
      return tr;
    }));
  }

  // ---------------- loading ----------------
  const FILES = ['kpi', 'daily', 'episodes', 'monthly', 'etf_daily', 'etf_summary', 'floor', 'floor_daily', 'nt_history'];

  function drawAll() {
    if (!D) return;
    const pal = palette();
    drawHeader(D.kpi);
    drawPoolTable();
    drawEpTable();
    drawCumulative(pal);
    drawCalendar(pal);
    drawMonthly();
    drawSmall(pal);
    drawHoldings();
    drawFloorDaily(pal);
  }

  $('take-now').textContent = t('common.loading');
  kit.sectionNav($('secnav'));
  kit.downloadLinks('data/');

  Promise.all(FILES.map((f) => kit.csv(`data/${f}.csv`))).then(([kpi, daily, episodes, monthly, etf, summary, floor, floorDaily, ntHist]) => {
    etfNameEn = new Map(summary.map((r) => [r.code, r.name_en]));
    const floorBy = new Map(floor.map((f) => [f.code, f]));
    const etfRows = etf.map((r) => ({ code: r.code, name: r.name, date: r.date, d: new Date(r.date), sh: num(r.shares_yi), flow: num(r.flow_yi) }));
    D = {
      kpi: kpi[0],
      daily: daily.map((r) => ({
        date: r.date, d: new Date(r.date), flow: num(r.flow_total),
        idx: num(r.csi300), ret: num(r.csi300_ret), signal: r.signal || '',
      })),
      episodeRows: episodes,
      episodes: episodes.map((e) => ({ s: new Date(e.start), e: new Date(e.end), side: e.side })),
      monthly: monthly.map((r) => {
        const o = { month: r.month, total: num(r.total) };
        FAM.forEach(([k]) => { o[k] = num(r[k]) || 0; });
        return o;
      }),
      etfByCode: d3.group(etfRows, (r) => r.code),
      etfByDate: d3.group(etfRows, (r) => r.date),
      summary,
      floor,
      // merged table: flow columns from etf_summary, holdings columns from floor (etf_summary wins on shared names)
      poolRows: summary.map((s) => ({ ...(floorBy.get(s.code) || {}), ...s })),
      floorDaily: floorDaily.map((r) => ({ date: r.date, d: new Date(r.date), v: num(r.floor_amt_yi) })),
      ntHist: ntHist.filter((r) => num(r.total) > 0).map((r) => {
        const o = { period_end: r.period_end, kind: r.kind, total: num(r.total) };
        FAM.forEach(([k]) => { o[k] = num(r[k]) || 0; });
        return o;
      }),
    };
    const [dMin, dMax] = d3.extent(D.daily, (r) => r.d);
    const pal = () => palette();
    R.cum = kit.rangePicker($('cum-range'), { min: dMin, max: dMax, onChange: () => drawCumulative(pal()) });
    R.cal = kit.rangePicker($('cal-range'), { min: dMin, max: dMax, onChange: () => drawCalendar(pal()) });
    R.mon = kit.rangePicker($('mon-range'), { min: dMin, max: dMax, onChange: () => drawMonthly() });
    R.sm = kit.rangePicker($('sm-range'), { min: dMin, max: dMax, onChange: () => drawSmall(pal()) });
    kit.markStale($('stale'), D.kpi.as_of);
    drawAll();
    document.querySelectorAll('#pool-mode button').forEach((b) => b.addEventListener('click', () => {
      poolMode = b.dataset.mode;
      drawPoolTable();
    }));
    kit.onRedraw(drawAll);
  }).catch((err) => {
    console.error(err);
    const show = () => { $('take-now').textContent = t('loadError', { cmd: UPDATE_CMD }); };
    show();
    i18n.onChange(show);
    ['cal-box', 'cum-box', 'mon-box', 'sm-box', 'hold-box', 'floor-box'].forEach((id) => kit.fail($(id)));
  });
})();
